#!/usr/bin/env bash
# Generated by orca-setup from .orca-setup.json; change that file or the kit, not this one.
# Remove a plan worktree after its merge and prove it is gone: `orca worktree rm --run-hooks`
# (the archive hook drops its stack), then the folder. Finder can write .DS_Store files while
# Orca deletes the folder; Orca then stops with "Directory not empty" and leaves the rest, which
# once left 5 GB of backups and media (facadesystems plan 018). Once git no longer lists the
# worktree, what is left is a plain folder, and this script deletes it.
# Run from the main checkout in an Orca terminal: `exec ./scripts/orca/remove-worktree.sh <NNN-slug>`.
# Prints "REMOVE OK" or "REMOVE FAILED: <step>"; output goes to .scratch/tmp/remove-worktree.log.
set -uo pipefail
cd "$(dirname "$0")/../.." || exit 1

name=${1:?usage: scripts/orca/remove-worktree.sh <NNN-slug>}
case "$name" in */*|.*|"") echo "remove-worktree: give the worktree name, not a path" >&2; exit 2 ;; esac
if [ "$(git rev-parse --absolute-git-dir)" != "$(git rev-parse --path-format=absolute --git-common-dir)" ]; then
  echo "remove-worktree: run it from the main checkout" >&2
  exit 1
fi

repo=$PWD
wt="$repo/.worktrees/$(basename "$repo")/$name"
mkdir -p .scratch/tmp
log="$repo/.scratch/tmp/remove-worktree.log"
: > "$log"
fail() { echo "REMOVE FAILED: $1" | tee -a "$log"; exit 1; }
registered() { git worktree list --porcelain | grep -qx "worktree $wt"; }

if registered || [ -d "$wt" ]; then
  echo "=== orca worktree rm $name" | tee -a "$log"
  out=$(orca worktree rm --worktree "path:$wt" --run-hooks --json 2>&1)
  echo "$out" >> "$log"
  # A failed archive hook stops Orca before anything is deleted; say so instead of waiting.
  if grep -q '"ok": false' <<<"$out" && registered; then
    code=$(grep -m1 '"code"' <<<"$out" | sed 's/.*"code": *"\([^"]*\)".*/\1/')
    fail "orca worktree rm: ${code:-error} (see $log)"
  fi
fi
for _ in $(seq 1 15); do
  [ -d "$wt" ] || break
  sleep 2
done
if registered; then
  fail "git still lists $name; rerun after closing Finder windows on it"
fi
for attempt in 1 2 3; do
  [ -d "$wt" ] || break
  echo "=== delete the leftover folder, attempt $attempt" | tee -a "$log"
  rm -rf "$wt" >> "$log" 2>&1 || sleep 2
done
[ -d "$wt" ] && fail "folder of $name is still there; close Finder windows on it and rerun"
if git show-ref --verify --quiet "refs/heads/task/$name"; then
  git branch -d "task/$name" >> "$log" 2>&1 || fail "branch task/$name was not deleted (not merged?)"
fi
echo "REMOVE OK" | tee -a "$log"
